mapper.select:
SELECT l.id, l.org_id, l.user_id, l.leader_type, l.duty_title, l.category, l.sort_no,
       l.effective_from, l.effective_to, l.remark, l.created_at, l.created_by, l.updated_at, l.updated_by
FROM sys_org_leader l
WHERE 1 = 1
  AND /* @dataScope(table=sys_org_leader, alias=ol) */
  AND l.org_id = #{orgId}
  AND l.user_id = #{userId}
  AND l.leader_type = #{leaderType}
  AND l.category <=> #{category}
LIMIT 1
